
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_xb1k_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_xb1k", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.520863693955774e+00, -2.473870590958238e+00, -2.408054184989783e+00, -2.316949410670496e+00, -2.192947627602700e+00, -2.028199668130346e+00, -1.816734748019550e+00, -1.558219186733679e+00, -1.262771722165998e+00, -9.526149047846545e-01, -6.513753735037561e-01, -4.594362684805685e-01, -3.817913401632717e-01, -3.112858688516688e-01, -2.265106448946815e-01, -1.455330355710196e-01, -8.602238363236550e-02, -4.500081014395003e-02, -2.663875676699128e-02, -1.819211714636854e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


